const input=$json.body??$json;
const status=String(input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const contractPrice=Number(input.contract_price??input.proposed_contract_price??0);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const provider=String(input.signature_provider??'').trim();
const envelopeId=String(input.envelope_id??input.signature_envelope_id??'').trim();
const signatureStatus=String(input.signature_status??input.execution_status??'').toLowerCase();
const idempotencyKey=String(input.idempotency_key??'').trim()||['WF-322',dealId,contractPrice].join(':');
const dnc=input.dnc===true||status==='blocked_dnc';
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const identityReady=Boolean(dealId&&leadId&&propertyId);
const priceProtected=mao>0&&contractPrice>0&&contractPrice<=mao;
let outcome='needs_review',next='WF-126',reason='signature state requires review';
if(dnc){outcome='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(blockers.length){outcome='blocked';next='WF-126';reason='active blockers';}
else if(!identityReady){outcome='incomplete_identity';next='WF-126';reason='deal/lead/property identity missing';}
else if(!priceProtected){outcome='above_mao';next='WF-126';reason='contract price exceeds dynamic MAO';}
else if(!provider){outcome='signature_provider_required';next='WF-126';reason='signature provider not configured';}
else if(signatureStatus==='executed'||status==='executed'){outcome='executed';next='WF-323';reason='signature execution confirmed';}
else if(signatureStatus==='declined'||signatureStatus==='rejected'||status==='declined'){outcome='declined';next='WF-204';reason='seller declined signature';}
else if(signatureStatus==='expired'||status==='expired'){outcome='expired';next='WF-204';reason='signature request expired';}
else if(signatureStatus==='awaiting_signature'||status==='awaiting_signature'){outcome='awaiting_signature';next='WF-323';reason='signature request is active and awaiting execution';}
else if(!envelopeId){outcome='dispatch_ready';next='WF-323';reason='validated package ready for signature dispatch';}
else{outcome='awaiting_signature';next='WF-323';reason='signature envelope exists; awaiting provider outcome';}
return [{json:{...input,workflow_id:'WF-322',workflow_name:'Signature Launch → Execution Tracking & Signature Outcome Controller',outcome,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,contract_price:contractPrice,dynamic_mao:mao,price_protected:priceProtected,signature_provider:provider,envelope_id:envelopeId||null,idempotency_key:idempotencyKey,next_workflow:next,human_review_required:['declined','expired','above_mao','blocked'].includes(outcome),crm_activity:{activity_type:'signature_execution',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:outcome,contract_price:contractPrice,envelope_id:envelopeId||null,reason}}}];
